// ① 부르는 쪽이 보는 타입
public interface MemberRepository
        extends JpaRepository<Member, Long>, MemberRepositoryCustom {
    List<Member> findByUsername(String username);
}

// ② 조립할 것만 선언
public interface MemberRepositoryCustom {
    List<MemberTeamDto> search(MemberSearchCondition cond);
}

// ③ 구현
public class MemberRepositoryCustomImpl implements MemberRepositoryCustom {

    private final JPAQueryFactory queryFactory;

    public MemberRepositoryCustomImpl(JPAQueryFactory queryFactory) {
        this.queryFactory = queryFactory;
    }

    @Override
    public List<MemberTeamDto> search(MemberSearchCondition cond) {
        return queryFactory
                .select(new QMemberTeamDto(
                        member.id, member.username, member.age,
                        team.id, team.name))
                .from(member)
                .leftJoin(member.team, team)
                .where(usernameEq(cond.getUsername()),
                       teamNameEq(cond.getTeamName()),
                       ageBetween(cond.getAgeGoe(), cond.getAgeLoe()))
                .fetch();
    }
}

