public interface MemberRepository extends
        JpaRepository<Member, Long>,
        MemberRepositoryCustom,
        MemberStatsRepositoryCustom {
}

public interface MemberStatsRepositoryCustom {
    List<TeamStat> teamStats();
}

public class MemberStatsRepositoryCustomImpl
        implements MemberStatsRepositoryCustom {

    private final JPAQueryFactory queryFactory;
    ...

    @Override
    public List<TeamStat> teamStats() {
        return queryFactory
                .select(new QTeamStat(team.name, member.count(),
                        member.age.avg()))
                .from(member)
                .join(member.team, team)
                .groupBy(team.name)
                .fetch();
    }
}

